UPDATE `review_form_responses` SET `response_value` = 'Metode penelitian belum dijelaskan/belum ada secara detail. Perlu ditambahkan. Lihat catatan pada naskah., Data belum mewakili populasi., Metode yang digunakan belum cukup kuat jika jumlah sampel benda uji hanya 3 benda uji untuk tiap kondisi umur beton' WHERE `review_form_element_id` = '6' AND `review_id` = '245';
