UPDATE `email_templates_default_data` SET `body` = 'Dear {$authorName}:<br />, <br />, This email confirms that {$bookForReviewTitle} has been assigned to you for a book review to be completed by {$bookForReviewDueDate}.<br />, <br />, Please ensure that your mailing address in your online user profile is up-to-date. This address will be used to mail a copy of the book to you for the review.<br />, <br />, The mailing address that we currently have on file is:<br />, {$authorMailingAddress}<br />, <br />, If this address is incomplete or you are no longer at this address, please use the following user profile URL to update your address:<br />, <br />, User Profile URL: <a href="{$userProfileUrl}">{$userProfileUrl}</a><br />,  <br />, To submit your book review, please log into the journal website and complete the online article submission process.<br />, <br />, Submission URL: <a href="{$submissionUrl}">{$submissionUrl}</a><br />, <br />, Please feel free to contact me if you have any questions or concerns about this book review.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_ASSIGNED' AND `locale` = 'tr_TR';
