UPDATE `email_templates_default_data` SET `body` = 'Kepada {$authorName}:<br />, <br />, Sayangnya, saya tidak bisa memberikan {$bookForReviewTitle}kepada Anda sekarang ini untuk review buku.  <br />, <br />, Saya harap Anda mempertimbangkan untuk mereview buku lain dari daftar kami, sekarang atau di masa depan. <br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_DENIED' AND `locale` = 'id_ID';
