UPDATE `email_templates_default_data` SET `body` = 'Beste {$authorName}:<br />, <br />, Helaas kan ik {$bookForReviewTitle} niet voor een bespreking aan u toekennen.<br />, <br />, Ik hoop dat u nu of in de toekomst wilt overwegen om een ander boek uit onze lijst te bespreken.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_DENIED' AND `locale` = 'nl_NL';
