UPDATE `email_templates_default_data` SET `body` = 'Dear {$authorName}:<br />, <br />, This email confirms that I have mailed a copy of {$bookForReviewTitle} to the following mailing address from your online user profile:<br />, {$authorMailingAddress}<br />,  <br />, To submit your book review, please log into the journal website and complete the online article submission process.<br />, <br />, Submission URL: <a href="{$submissionUrl}">{$submissionUrl}</a><br />, <br />, Please feel free to contact me if you have any questions or concerns about this book review.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_MAILED' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = 'Estimado/a {$authorName}:<br /><br />Este correo electrónico confirma que envié una copia de {$bookForReviewTitle} a la siguiente dirección postal de su perfil de usuario/a: {$authorMailingAddress}<br /><br />Para enviar la reseña de libro, inicie sesión en el sitio web de la revista y complete el proceso de envío de artículos en línea.<br /><br />URL del envío: <a href="{$submissionUrl}">{$submissionUrl}</a><br /><br />Si tiene cualquier pregunta o comentario sobre la reseña de libro, no dude en ponerse en contacto conmigo.<br /><br />{$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_MAILED' AND `locale` = 'es_ES';
