UPDATE `email_templates_default_data` SET `body` = 'Beste {$authorName}:<br />, <br />, Met deze e-mail bevestig ik dat ik een exemplaar van {$bookForReviewTitle} heb verstuurd naar het volgende adres uit uw gebruikersprofiel:<br />, {$authorMailingAddress}<br />,  <br />, Om uw bespreking in te dienen, kunt u inloggen op de website van het tijdschrift en het online indienen van een artikel uitvoeren.<br />, <br />, URL: <a href="{$submissionUrl}">{$submissionUrl}</a><br />, <br />, Voel u vrij om contact met me op te nemen als u vragen heeft over deze boekbespreking.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_BOOK_MAILED' AND `locale` = 'nl_NL';
