UPDATE `email_templates_default_data` SET `body` = 'Kepada {$authorName}:<br />, <br />, Email ini mengkonfirmasi bahwa Anda telah dipindahkan sebagai reviewer buku untuk {$bookForReviewTitle}, yang akan menjadi tersedia untuk penulis lain yang tertarik mereview buku. <br />, <br />, Saya harap Anda bersedia mereview buku lain dari daftar kamu, baik sekarang maupun lain waktu. <br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_REVIEWER_REMOVED' AND `locale` = 'id_ID';
