UPDATE `email_templates_default_data` SET `body` = 'Beste {$authorName}:<br />, <br />, Dit is een vriendelijke herinnering dat uw boekbespreking van {$bookForReviewTitle} verwacht was op {$bookForReviewDueDate}, maar nog niet door ons is ontvangen.<br />, <br />, Om uw bespreking in te sturen, kunt u inloggen op de website van het tijdschrift en het online inzenden van een artikel doorlopen. Om het u makkelijk te maken vindt u hieronder een URL voor het inzenden.<br />, <br />, URL voor uw inzending: <a href="{$submissionUrl}">{$submissionUrl}</a><br />, <br />, Voel u vrij om contact met mij op te nemen als u vragen heeft over deze boekbespreking.<br />, <br />, Ik dank u voor uw bijdrage aan het tijdschrift en kijk uit naar het ontvangen van uw bijdrage.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'BFR_REVIEW_REMINDER_LATE' AND `locale` = 'nl_NL';
