UPDATE `email_templates_default_data` SET `body` = 'Ein Indizierungsfehler ist bei der Aktualisierung des Artikel-Index aufgetreten.<br />, <br />, Die eventuell aufgetretene Fehlermeldung lautete: "{$error}"<br />, <br />, Diese E-Mail wurde durch das Lucene-Suche-Plug-In von Open Journal Systems erzeugt.' WHERE `email_key` = 'LUCENE_ARTICLE_INDEXING_ERROR_NOTIFICATION' AND `locale` = 'de_DE';
