UPDATE `email_templates_default_data` SET `body` = 'Benvolgut/da {$authorName}:<br /><br />Desgraciadament, en aquests moments no us podem assignar {$objectForReviewTitle} com a objecte de revisió.<br /><br />Esperem que considereu revisar altres objectes de la nostre llista, ja sigui ara o en un futur.<br /><br />{$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_DENIED' AND `locale` = 'ca_ES';
UPDATE `email_templates_default_data` SET `body` = 'VáÅ¾ená paní/váÅ¾enÃ½ pane {$authorName}:<br /><br />BohuÅ¾el vám jiÅ¾ nemohu pÅ™idÄ›lit k recenzi objekt {$objectForReviewTitle}.<br /><br />Doufáme, Å¾e si k recenzi vyberete jinÃ½ z objektÅ¯ na naÅ¡em seznamu buÄ hned teÄ, Äi kdykoliv v budoucnu.<br /><br />{$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_DENIED' AND `locale` = 'cs_CZ';
UPDATE `email_templates_default_data` SET `body` = 'KÃ¦re {$authorName}:<br />, <br />, DesvÃ¦rre kan jeg ikke denne gang tildele dig {$objectForReviewTitle} til viderebedÃ¸mmelse.<br />, <br />, Jeg hÃ¥ber, du vil overveje at bedÃ¸mme et andet objekt fra vores liste enten nu eller senere.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_DENIED' AND `locale` = 'da_DK';
UPDATE `email_templates_default_data` SET `body` = 'Liebe/r {$authorName},<br /><br />leider kann ich Ihnen {$objectForReviewTitle} derzeit nicht zu einer Rezension zuteilen.<br /><br />Ich hoffe, dass Sie in Erwägung ziehen, ein anderes Objekt aus unserer Liste zu besprechen - jetzt oder in Zukunft.<br /><br />{$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_DENIED' AND `locale` = 'de_DE';
