UPDATE `email_templates_default_data` SET `body` = 'Apreciado/da {$authorName}:<br /><br />Desgraciadamente, en estos momentos no te podemos asignar {$objectForReviewTitle} como objeto de revisión.<br /><br />Esperamos que consideres revisar otros objetos de nuestra lista, ja sea ahora o en un futuro.<br /><br />{$editorialContactSignature}' WHERE `email_key` = 'OFR_OBJECT_DENIED' AND `locale` = 'es_ES';
