UPDATE `email_templates_default_data` SET `body` = 'Readers:<br />, <br />, {$contextName} has just made available in an open access format the following issue. We invite you to review the Table of Contents here and then visit our web site ({$contextUrl}) to review articles and items of interest.<br />, <br />, Thanks for the continuing interest in our work,<br />, {$editorialContactSignature}' WHERE `email_key` = 'OPEN_ACCESS_NOTIFY' AND `locale` = 'en_US';
