UPDATE `email_templates_default_data` SET `body` = 'Ø¹Ø²ÙŠØ²Ù†Ø§ {$authorName}ØŒ, Ù„Ù‚Ø¯ ØªÙ… Ø¥Ø¯Ø±Ø§Ø¬Ùƒ Ø¨Ù…Ø«Ø§Ø¨Ø© Ù…Ø¤Ù„Ù Ù…Ø´Ø§Ø±Ùƒ ÙÙŠ Ø§Ù„Ø¹Ù…Ù„ Ø§Ù„Ù…ÙˆØ³ÙˆÙ… "{$articleTitle}" ÙˆØ§Ù„Ù…Ù‚Ø¯Ù… Ø¥Ù„Ù‰ {$journalName}. , Ù„ØªØ£ÙƒÙŠØ¯ Ù…ØµØ§Ø¯Ù‚ØªÙƒØŒ Ù„Ø·ÙØ§Ù‹ØŒ Ø£Ø¶Ù Ø±Ù…Ø²Ùƒ Ø§Ù„ØªØ¹Ø±ÙŠÙÙŠ ÙÙŠ ORCID Ø¥Ù„Ù‰ Ø·Ù„Ø¨ Ø§Ù„ØªÙ‚Ø¯ÙŠÙ… Ù‡Ø°Ø§ Ø¹Ø¨Ø± Ø²ÙŠØ§Ø±Ø© Ø§Ù„Ø±Ø§Ø¨Ø· Ø£Ø¯Ù†Ø§Ù‡., {$authorOrcidUrl}, Ø¥Ø°Ø§ ÙƒØ§Ù†Øª Ù„Ø¯ÙŠÙƒ Ø£ÙŠ Ø§Ø³ØªÙØ³Ø§Ø±Ø§ØªØŒ Ø±Ø¬Ø§Ø¡Ù‹ØŒ Ù„Ø§ ØªØªØ±Ø¯Ø¯ ÙÙŠ Ù…Ø±Ø§Ø³Ù„ØªÙŠ., {$editorialContactSignature}, ' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'ar_IQ';
UPDATE `email_templates_default_data` SET `body` = 'VáÅ¾enÃ½(á) {$authorName},Byl(a) jste uveden(a) jako spoluautor rukopisu pÅ™íspÄ›vku "{$articleTitle}" do Äasopisu {$journalName}. K potvrzení vaÅ¡eho autorství vloÅ¾te, prosím vaÅ¡e ORCID k pÅ™íspÄ›vku na následující webové adrese.{$authorOrcidUrl}Pokud máte jakékoliv dotazy, neváhejte mne kontaktovat.{$editorialContactSignature}' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'cs_CZ';
UPDATE `email_templates_default_data` SET `body` = 'KÃ¦re {$authorName},<br/>, <br/>, Du stÃ¥r opfÃ¸rt som medforfatter til manuskriptet "{$articleTitle}" i {$contextName}.<br/>, <br/>, For at bekrÃ¦fte forfatterskabet bedes du tilfÃ¸je din ORCID id til denne indsendelse ved at gÃ¥ til det fremlagte link nedenfor.<br/>, <br/>, {$authorOrcidUrl}<br/>, <br/>, Har du spÃ¸rgsmÃ¥l bedes du kontakte mig.<br/>, <br/>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'da_DK';
UPDATE `email_templates_default_data` SET `body` = 'Liebe/r {$authorName},<br/><br/>Sie sind als Autor/in eines eingereichten Beitrags bei der Zeitschrift {$contextName} benannt worden.<br/><br/>Um Ihre Autor/innenschaft zu bestätigen, geben Sie bitte Ihre ORCID iD für diese Einreichung an, indem Sie den unten angegebenen Link aufrufen.<br/><a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>ORCID iD registrieren oder ihre verbinden</a><br/><br/><br/><a href="{$orcidAboutUrl}">Mehr Informationen zu ORCID bei {$contextName}</a><br/><br/>Wenn Sie Fragen dazu haben, melden Sie sich bitte bei mir.<br/><br/>{$principalContactSignature}<br/>' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'de_DE';
UPDATE `email_templates_default_data` SET `body` = 'Dear {$authorName},<br/>, <br/>, You have been listed as an author on a manuscript submission to {$contextName}.<br/>, To confirm your authorship, please add your ORCID id to this submission by visiting the link provided below.<br/>, <br/>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Register or connect your ORCID iD</a><br/>, <br/>, <br>, <a href="{$orcidAboutUrl}">More information about ORCID at {$contextName}</a><br/>, <br/>, If you have any questions, please contact me.<br/>, <br/>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = 'Estimado/a {$authorName},Se le ha añadido como coautor/a del artículo "{$articleTitle}" para {$journalName}. Para confirmar su autoría, añada su identificador ORCID a este envío mediante el enlace proporcionado a continuación.{$authorOrcidUrl}Si tiene cualquier pregunta no dude en contactarme.{$editorialContactSignature}' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'es_ES';
UPDATE `email_templates_default_data` SET `body` = 'Arvoisa {$authorName},<br/><br/>Teidät mainitaan käsikirjoituksen "{$articleTitle}" yhdeksi kirjoittajaksi, joka on lähetetty lehteen {$contextName}.<br/><br/>Varmistaaksesi tekijyytesi, ole hyvä ja lisää ORCID-tunnisteesi käsikirjoitukseen vierailemalla alla olevassa linkissä.<br/><br/>{$authorOrcidUrl}<br/><br/>Mikäli teillä on jotain kysymyksiä, olkaa yhteydessä.<br/><br/>{$principalContactSignature}<br/>' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'fi_FI';
UPDATE `email_templates_default_data` SET `body` = '{$authorName},<br/>\\\\<br/>\\\\Vous avez été inscrit ou inscrite en tant qu''auteur ou auteure pour un manuscrit soumis Ã  {$contextName}.<br/>\\\\Pour confirmer votre statut d''auteur ou d''auteure, veuillez ajouter votre identifiant ORCID Ã  cette soumission en cliquant sur le lien ci-dessous.<br/>\\\\<br/>\\\\<a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="icÃ´ne identifiant ORCID" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Se connecter avec votre identifiant ORCID ou s''inscrire</a><br/>\\\\<br/>\\\\<br/>\\\\<a href="{$orcidAboutUrl}">Plus de renseignements sur votre identifiant ORCID dans {$contextName}</a><br/>\\\\<br/>\\\\Si vous avez des questions, veuillez communiquer avec nous.<br/>\\\\<br/>\\\\{$principalContactSignature}<br/>\\\\' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'fr_CA';
UPDATE `email_templates_default_data` SET `body` = 'Yang Kami Hormati {$authorName},<br/>, <br/>, Anda telah terdaftar sebagai penulis naskah{$contextName}.<br/>, Untuk mengonfirmasi kepenulisan tersebut, tambahkanlah id ORCID Anda pada naskah tersebut dengan membuka tautan berikut ini.<br/>, <br/>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Register atau hubungkan iD ORCID Anda</a><br/>, <br/>, <br>, <a href="{$orcidAboutUrl}">Informasi selengkapnya tentang ORCID pada {$contextName}</a><br/>, <br/>, Bila ada pertanyaan, silakan hubungi kami.<br/>, <br/>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'id_ID';
UPDATE `email_templates_default_data` SET `body` = 'Gentile {$authorName},\\\\\\\\Lei è stato indicato come co-autore della proposta "{$articleTitle}" giunta alla rivista {$journalName}. \\\\\\\\Per confermare la sua responsabilitÃ  come autore, le chiediamo di aggiungere il suo codice ORCID alla proposta usando il link messo qui sotto.\\\\\\\\{$authorOrcidUrl}\\\\\\\\Se delle domandi, mi contatti pure.\\\\\\\\{$editorialContactSignature}\\\\\\\\\\\\' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'it_IT';
UPDATE `email_templates_default_data` SET `body` = 'Beste {$authorName},<br/>, <br/>, U bent auteur van een inzending voor {$contextName}.<br/> , Wilt u bevestigen dat u co-auteur bent door uw ORCID id toe te voegen via volgende link?<br/>, <br/>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Registreer of koppel uw ORCID ID</a><br/>, <br/>, <br/>, <a href="{$orcidAboutUrl}">Meer informatie over ORCID op {$contextName}</a><br/>, <br/>, Neemt u alstublieft contact op als u vragen heeft.<br/>, <br/>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'nl_NL';
UPDATE `email_templates_default_data` SET `body` = 'Prezada(o) {$authorName},VocÃª foi listada(o) como um coautor(a) em uma submissÃ£o de manuscrito "{$articleTitle}" para {$journalName}.Para confirmar sua autoria, por favor adicione sua id ORCID a esta submissÃ£o, visitando o link fornecido abaixo.{$authorOrcidUrl}Se vocÃª tiver quaisquer dúvidas, por favor entre em contato comigo.{$editorialContactSignature}' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'pt_BR';
UPDATE `email_templates_default_data` SET `body` = 'Caro(a) {$authorName},\\\\\\\\O seu nome foi indicado como coautor do manuscrito "{$articleTitle}" submetido Ã  revista {$journalName}. \\\\\\\\Para confirmar a sua autoria, por favor adicione o seu identificador ORCID Ã  submissÃ£o visitando a página indicada abaixo.\\\\\\\\{$authorOrcidUrl}\\\\\\\\Se tiver alguma dúvida, por favor contacte-me.\\\\\\\\{$editorialContactSignature}\\\\\\\\\\\\' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'pt_PT';
