UPDATE `email_templates_default_data` SET `body` = 'SpoÅ¡tovani {$authorName},<br/>, <br/>, Navedeni ste bili kot soavtor rokopisa prispevka za revijo{$contextName}.<br/>, Da potrdite avtorstvo, vas prosimo, da dodate vaÅ¡ ORCID iD v prispevek s klikom na spodnjo povezavo.<br/>, <br/>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Registracija ali povezava z vaÅ¡im ORCID iD</a><br/>, <br/>, <br/>, <a href="{$orcidAboutUrl}">VeÄ o ORCID pri reviji {$contextName}</a><br/>, <br/>, ÄŒe imate kakrÅ¡nakoli vpraÅ¡anje, me prosim kontaktirajte.<br/>, <br/>, {$principalContactSignature}<br/>' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'sl_SI';
UPDATE `email_templates_default_data` SET `body` = 'Hej {$authorName}!Du är listad som medförfattare till bidraget "{$articleTitle}" till {$journalName}. För att bekräfta ditt författarskap, lägg till ditt ORCID-iD genom att följa länken nedan.{$authorOrcidUrl}Kontakta gärna mig om du har nÃ¥gra frÃ¥gor.{$editorialContactSignature}' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'sv_SE';
UPDATE `email_templates_default_data` SET `body` = 'SayÄ±n {$authorName},{$journalName} adlÄ± dergiye sunulan "{$articleTitle}" adlÄ± makale için ortak yazar olarak belirtildiniz.YazarlÄ±ÄŸÄ±nÄ±zÄ± onaylamak için lütfen aÅŸaÄŸÄ±daki baÄŸlantÄ±yÄ± ziyaret ederek ORCID kimliÄŸinizi dergimize ekleyiniz.{$authorOrcidUrl}Herhangi bir sorunuz olmasÄ± halinde, lütfen bize yazÄ±nÄ±z.{$editorialContactSignature}' WHERE `email_key` = 'ORCID_COLLECT_AUTHOR_ID' AND `locale` = 'tr_TR';
