UPDATE `email_templates_default_data` SET `body` = 'Liebe/r {$authorName},<br><br>Sie sind als Autor/in eines eingereichten Beitrags bei der Zeitschrift {$contextName} benannt worden.<br><br>Bitte gestatten Sie uns ihre ORCID-ID, falls vorhanden, zu diesem Beitrag hinzuzufügen, sowie ihr ORCID Profil bei Veröffentlichung des Beitrags zu aktualisieren.<br>Dazu folgen sie dem unten stehenden Link zur offiziellen ORCID-Seite, melden sich mit ihren Daten an und authorisieren sie den Zugriff, indemsie den Anweisungen auf der Seite folgen.<br><a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>ORCID iD registrieren oder ihre verbinden</a><br/><br/><br><a href="{$orcidAboutUrl}">Mehr Informationen zu ORCID bei {$contextName}</a>.<br>Wenn Sie Fragen dazu haben, melden Sie sich bitte.<br><br>{$principalContactSignature}<br>' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'de_DE';
UPDATE `email_templates_default_data` SET `body` = 'Dear {$authorName},<br>, <br>, You have been listed as an author on the manuscript submission "{$articleTitle}" to {$contextName}., <br>, <br>, Please allow us to add your ORCID id to this submission and also to add the submission to your ORCID profile on publication.<br>, Visit the link to the official ORCID website, login with your profile and authorize the access by following the instructions.<br>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Register or Connect your ORCID iD</a><br/>, <br>, <br>, <a href="{$orcidAboutUrl}">More about ORCID at {$contextName}</a><br/>, <br>, If you have any questions, please contact me.<br>, <br>, {$principalContactSignature}<br>, ' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = '{$authorName},<br/>\\\\<br/>\\\\Vous avez été inscrit ou inscrite en tant qu''auteur ou auteure pour le manuscrit « {$articleTitle} » soumis Ã  {$contextName}.\\\\<br/>\\\\<br/>\\\\Veuillez nous autoriser Ã  ajouter votre identifiant ORCID Ã  cette soumission et Ã  ajouter également la soumission Ã  votre dossier ORCID suite Ã  sa publication.\\\\<br/>\\\\Suivre le lien vers le site officiel ORCID, vous connecter avec votre profil et autoriser l''accès en suivant les instructions.<br/>\\\\<a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="icÃ´ne identifiant ORCID" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Se connecter avec votre identifiant ORCID ou s''inscrire</a><br/>\\\\<br/>\\\\<br/>\\\\<a href="{$orcidAboutUrl}">Plus de renseignements sur votre identifiant ORCID dans {$contextName}</a><br/>\\\\<br/>\\\\Si vous avez des questions, veuillez communiquer avec nous.<br/>\\\\<br/>\\\\{$principalContactSignature}<br/>\\\\' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'fr_CA';
UPDATE `email_templates_default_data` SET `body` = 'Yang Kami Hormati {$authorName},<br>, <br>, Anda telah terdaftar sebagai penulis naskah "{$submissionTitle}" pada {$contextName}., <br>, <br>, Ijinkanlah kami menambahkan id ORCID Anda pada naskah ini serta menambahkan naskah pada profil ORCID Anda pada terbitan.<br>, Buka tautan web ORCID, login dan beri akses sesuai petunjuk berikut.<br>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Register atau hubungkan iD ORCID Anda</a><br/>, <br>, <br>, <a href="{$orcidAboutUrl}">nformasi selengkapnya tentang ORCID pada {$contextName}</a><br/>, <br>, Bila ada pertanyaan, silakan hubungi kami.<br>, <br>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'id_ID';
UPDATE `email_templates_default_data` SET `body` = 'Beste {$authorName},<br/>, <br/>, U bent auteur van het manuscript "{$articleTitle}" dat werd ingediend voor {$contextName}., <br/>, <br/>, Wilt u uw toestemming geven om uw ORCID ID toe te voegen aan deze inzending en de inzending toe te voegen aan uw ORCID profiel bij publicatie?<br/>, Klik op de link naar de officiÃ«le ORCID website, meld u aan met uw gebruikersprofiel en authoriseer de toegang door de instructies te volgen.<br/>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Registreer of koppel uw ORCID ID</a><br/>, <br/>, <br/>, <a href="{$orcidAboutUrl}">Meer informatie over ORCID op {$contextName}</a><br/>, <br>, Neemt u alstublieft contact op als u vragen heeft.<br/>, <br/>, {$principalContactSignature}<br/>, ' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'nl_NL';
UPDATE `email_templates_default_data` SET `body` = 'SpoÅ¡tovani {$authorName},<br>, <br>, NaÅ¡teti ste bili kot (so)avtor rokopisa prispevka "{$articleTitle}" pri reviji {$contextName}., <br>, <br>, Prosimo vas za dovoljenje, da dodamo vaÅ¡ ORCID iD k temu prispevku in hkrati dodamo ta prispevek k vaÅ¡em ORCID profilu pri reviji.<br>, Kliknite na povezavo na uradno ORCID stran, prijavite se z vaÅ¡im profilom in avtorizirajte dostop po navodilih.<br>, <a href="{$authorOrcidUrl}"><img id="orcid-id-logo" src="https://orcid.org/sites/default/files/images/orcid_16x16.png" width=''16'' height=''16'' alt="ORCID iD icon" style="display: block; margin: 0 .5em 0 0; padding: 0; float: left;"/>Registriraj ali poveÅ¾i vaÅ¡ ORCID iD</a><br/>, <br>, <br>, <a href="{$orcidAboutUrl}">VeÄ o ORCID pri reviji {$contextName}</a><br/>, <br>, ÄŒe imate kakrÅ¡nakoli vpraÅ¡anje, me prosim kontaktirajte.<br/>, <br>, {$principalContactSignature}<br>' WHERE `email_key` = 'ORCID_REQUEST_AUTHOR_AUTHORIZATION' AND `locale` = 'sl_SI';
UPDATE `email_templates_default_data` SET `body` = 'La vostra contrasenya per al lloc web {$siteTitle} s''ha reinicialitzat correctament. Recordeu aquest nom d''usuari i aquesta contrasenya, ja que els necessitareu per a accedir a la revista i treballar-hi.<br />, <br />, Nom d''usuari: {$username}<br />, Contrasenya: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'ca_ES';
UPDATE `email_templates_default_data` SET `body` = 'VaÅ¡e heslo pro stránku {$siteTitle} bylo úspÄ›Å¡nÄ› resetováno. Zapamatujte si prosím toto uÅ¾ivatelské jméno a heslo, protoÅ¾e je budete potÅ™ebovat pro veÅ¡kerou práci s tímto Äasopisem.<br /><br />VaÅ¡e uÅ¾ivatelské jméno: {$username}<br />Heslo: {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'cs_CZ';
UPDATE `email_templates_default_data` SET `body` = 'Din adgangskode er blevet nulstillet og kan benyttes pÃ¥ webstedet {$siteTitle}. Opbevar brugernavnet og adgangskoden, da de er nÃ¸dvendige for alt arbejde i forbindelse med tidsskriftet.<br />, <br />, Dit brugernavn: {$username}<br/>, Adgangskode: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'da_DK';
UPDATE `email_templates_default_data` SET `body` = 'Ihr Benutzer/innen-Passwort für die Webseite {$siteTitle} wurde neu gesetzt. Bitte notieren Sie Benutzer/innennamen und Passwort, beides wird für alle Arbeiten mit dieser Zeitschrift gebraucht.<br /><br />Ihr Benutzer/innenname: {$username}<br />Passwort: {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'de_DE';
UPDATE `email_templates_default_data` SET `body` = 'Your password has been successfully reset for use with the {$siteTitle} web site. Please retain this username and password, as it is necessary for all work with the journal.<br />, <br />, Your username: {$username}<br />, Password: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = 'Su contraseña en {$siteTitle} se ha cambiado sin problema. Por favor, guarde en lugar seguro su nombre de usuaria/o y contraseña, ya que son necesarios para trabajar con la revista.<br /><br />Nombre de usuaria/o: {$username}<br />Contraseña: {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'es_ES';
UPDATE `email_templates_default_data` SET `body` = '{$siteTitle} webgunean sartzeko pasahitza ongi berrezarri da. Ondo gorde erabiltzaile-izen eta pasahitz hauek, aldizkarian sartzeko beharko baitituzu.<br />, <br />, Zure erabiltzaile-izena: {$username}<br />, Pasahitza: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'eu_ES';
UPDATE `email_templates_default_data` SET `body` = 'Salasananne {$siteTitle} -sivustolle on vaihdettu onnistuneesti. Säilyttäkää tämä käyttäjätunnus ja salasana, sillä tarvitsette niitä kaikkeen työskentelyyn julkaisun parissa.<br><br />Käyttäjätunnuksenne: {$username}<br />Salasana: {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'fi_FI';
UPDATE `email_templates_default_data` SET `body` = 'Votre mot de passe pour le site Web {$siteTitle} a été réinitialisé avec succès. Veuillez conserver votre nom d''utilisateur-trice ainsi que votre mot de passe. Vous en aurez besoin pour chacune de vos interactions avec la revue.<br /><br />Votre nom d''utilisateur-trice : {$username}<br />Mot de passe : {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'fr_CA';
UPDATE `email_templates_default_data` SET `body` = 'Votre mot de passe pour le site Web {$siteTitle} a été réinitialisé avec succès. Veuillez conserver précieusement votre nom d''utilisateur ainsi que votre mot de passe. Vous en aurez besoin pour chacune de vos interactions avec la revue.<br /><br />Votre nom d''utilisateur : {$username}<br />Votre nouveau mot de passe : {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'fr_FR';
UPDATE `email_templates_default_data` SET `body` = 'VaÅ¡a lozinka za mreÅ¾nu stranicu {$siteTitle} je uspjeÅ¡no promijenjena. Molimo vas da pohranite vaÅ¡e korisniÄko ime i lozinku jer su oni nuÅ¾ni za sve aktivnosti vezane uz Äasopis.<br />, <br />, VaÅ¡e korisniÄko ime: {$username}<br />, Lozinka: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'hr_HR';
UPDATE `email_templates_default_data` SET `body` = 'Sandi akun Anda di website {$siteTitle} telah berhasil di-reset. Silakan simpan nama pengguna dan sandi ini karena akan dibutuhkan untuk semua kegiatan terkait jurnal di website ini.<br />, <br />, Nama pengguna Anda: {$username}<br />, Sandi: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'id_ID';
UPDATE `email_templates_default_data` SET `body` = '&lt;![CDATA[La tua password per {$siteTitle} &amp;#232; stata modificata con successo.<br />, Qui sotto trovi il tuo username e la nuova password.<br />, <br />, La tua username: {$username}<br />, Password: {$password}<br />, <br />, {$principalContactSignature}]]&gt;' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'it_IT';
UPDATE `email_templates_default_data` SET `body` = 'Passordet ditt til nettstedet for {$siteTitle} er nÃ¥ fornyet. Ta godt vare pÃ¥ brukernavnet og passordet, som du vil trenge for de oppgavene du skal utfÃ¸re pÃ¥ nettstedet.<br />, <br />, Ditt brukernavn: {$username}<br />, Passord: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'nb_NO';
UPDATE `email_templates_default_data` SET `body` = 'Uw wachtwoord is met succes hersteld voor de website {$siteTitle}. Bewaar de gebruikersnaam en wachtwoord, ze zijn nodig om het tijdschrift te kunnen gebruiken.<br />, <br />, Uw gebruikersnaam: {$username}<br />, Wachtwoord: {$password}<br />, <br />, {$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'nl_NL';
UPDATE `email_templates_default_data` SET `body` = 'Sua senha de acesso ao site {$siteTitle} foi atualizada com sucesso. Guarde o login e a senha, uma vez que serÃ£o necessários para todas as atividades relacionadas ao sistema.<br /><br />Seu login: {$username}<br />Senha: {$password}<br /><br />{$principalContactSignature}' WHERE `email_key` = 'PASSWORD_RESET' AND `locale` = 'pt_BR';
