UPDATE `email_templates_default_data` SET `body` = 'Open Journal Systems ha notado una actividad inusual relacionada con el soporte de pago de PayPal para la revista {$contextName}.  Esta actividad puede necesitar de mayor investigación o intervención manual.<br /><br />Este email ha sido generado por el plugin de PayPal de Open Journal Systems.<br /><br />Información completa de envío para la solicitud:<br />{$postInfo}<br /><br />Información adicional (si proporcionada):<br />{$additionalInfo}<br /><br />Variables de servidor:<br />{$serverVars}' WHERE `email_key` = 'PAYPAL_INVESTIGATE_PAYMENT' AND `locale` = 'es_ES';
