UPDATE `email_templates_default_data` SET `body` = 'Open Journal Systems on havainnut epätavallista toimintaa julkaisun {$contextName} PayPal-maksujen tukeen liittyen. Tämä toiminta saattaa vaatia lisätutkimista tai manuaalista asiaan puuttumista.<br />                       <br />Tämä sähköposti on Open Journal Systemsin PayPal-lisäosan luoma.<br /><br />Pyynnön täydet lähetystiedot :<br />{$postInfo}<br /><br />Lisätiedot (mikäli annettu):<br />{$additionalInfo}<br /><br />Palvelimen muuttujat:<br />{$serverVars}<br />' WHERE `email_key` = 'PAYPAL_INVESTIGATE_PAYMENT' AND `locale` = 'fi_FI';
UPDATE `email_templates_default_data` SET `body` = 'L''Open Journal Systems a remarqué une activité inhabituelle concernant la prise en charge du paiement PayPal pour la revue {$contextName}. Cette activité pourrait nécessiter une attention particulière ou une intervention manuelle.<br />                       <br />Ce courriel a été généré par le plugiciel PayPal du Open Journal Systems.<br /><br />Information complète de la demande :<br />{$postInfo}<br /><br />Information supplémentaire (si fournie) :<br />{$additionalInfo}<br /><br />Variables serveur :<br />{$serverVars}<br />' WHERE `email_key` = 'PAYPAL_INVESTIGATE_PAYMENT' AND `locale` = 'fr_CA';
