UPDATE `email_templates_default_data` SET `body` = '{$authorName}:<br />, <br />, Thank you for proofreading the galleys for your manuscript, "{$submissionTitle}," in {$contextName}. We are looking forward to publishing your work shortly.<br />, <br />, If you subscribe to our notification service, you will receive an email of the Table of Contents as soon as it is published. If you have any questions, please contact me.<br />, <br />, {$editorialContactSignature}' WHERE `email_key` = 'PROOFREAD_AUTHOR_ACK' AND `locale` = 'en_US';
