UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br />\\\\<br />\\\\Nous vous remercions d''avoir évalué la soumission intitulée « {$submissionTitle} » pour {$contextName}. Nous vous sommes reconnaissants de votre contribution Ã  la qualité des travaux que nous publions.<br />\\\\<br />\\\\' WHERE `email_key` = 'REVIEW_ACK' AND `locale` = 'fr_FR';
