UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br />, <br />, We have decided at this point to cancel our request for you to review the submission, "{$submissionTitle}," for {$contextName}. We apologize for any inconvenience this may cause you and hope that we will be able to call on you to assist with this journal''s review process in the future.<br />, <br />, If you have any questions, please contact me.<br />, <br />, ' WHERE `email_key` = 'REVIEW_CANCEL' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br /><br />Decidimos cancelar nuestra solicitud para que revise el envío "{$submissionTitle}" para {$contextName}. Le pedimos disculpas por los inconvenientes que puedan surgir y esperamos que vuelva a colaborar con nosotros en el proceso de revisión de esta revista en el futuro.<br /><br />Si tiene cualquier pregunta, póngase en contacto conmigo.<br /><br />' WHERE `email_key` = 'REVIEW_CANCEL' AND `locale` = 'es_ES';
UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br />\\\\<br />\\\\Nous avons décidé d''annuler notre demande concernant l''évaluation du manuscrit intitulé « {$submissionTitle} » pour {$contextName}. Nous sommes désolés des inconvénients que cela pourrait vous causer et nous espérons que nous pourrons compter sur votre collaboration pour un autre projet.<br />\\\\<br />\\\\Si vous avez des questions, n''hésitez pas Ã  communiquer avec nous.<br />\\\\<br />\\\\' WHERE `email_key` = 'REVIEW_CANCEL' AND `locale` = 'fr_FR';
UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br />, <br />, Kami memutuskan untuk membatalkan permohonan review kami kepada Anda untuk naskah, &quot;{$submissionTitle},&quot; di {$contextName}. Kami mohon maaf sebesar-besarnya untuk ketidaknyamanan ini dan kami harap di masa mendatang Anda dapat membantu proses review di jurnal ini.<br />, <br />, Jika ada pertanyaan, silakan hubungi kami.' WHERE `email_key` = 'REVIEW_CANCEL' AND `locale` = 'id_ID';
UPDATE `email_templates_default_data` SET `body` = '{$reviewerName}:<br /><br />å‡ºäºŽç§ç§è€ƒé‡ï¼Œæˆ‘ä»¬ç›®å‰å·²ç»å–æ¶ˆäº†é‚€è¯·æ‚¨è¿›è¡ŒæŠ•ç¨¿ã€Š{$contextName}ã€‹ä¹‹ç¨¿ä»¶ã€ˆ{$submissionTitle}ã€‰çš„å®¡æŸ¥å·¥ä½œã€‚é€ æˆæ‚¨çš„ä¸ä¾¿ï¼Œæˆ‘ä»¬æ„Ÿåˆ°ååˆ†æŠ±æ­‰ï¼ŒåŒæ—¶æˆ‘ä»¬å¸Œæœ›åœ¨æœªæ¥ä»èƒ½å¤Ÿè¯·æ‚¨ååŠ©å®¡æŸ¥è¿™ä»½æœŸåˆŠçš„ç¨¿ä»¶ã€‚<br /><br />å¦‚æžœæ‚¨æœ‰ä»»ä½•é—®é¢˜ï¼Œè¯·ä¸Žæˆ‘ä»¬è”ç»œã€‚<br /><br />' WHERE `email_key` = 'REVIEW_CANCEL' AND `locale` = 'zh_CN';
UPDATE `email_templates_default_data` SET `body` = '{$editorialContactName}:<br />, <br />, I have now completed my review of "{$submissionTitle}" for {$contextName}, and submitted my recommendation, "{$recommendation}."<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_COMPLETE' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = '{$editorialContactName}:<br /><br />Completé mi revisión de "{$submissionTitle}" para {$contextName} y envié mi recomendación, "{$recommendation}".<br /><br />{$reviewerName}' WHERE `email_key` = 'REVIEW_COMPLETE' AND `locale` = 'es_ES';
