UPDATE `email_templates_default_data` SET `body` = '{$editorialContactName}:<br />, <br />, æˆ‘ç›®å‰å·²ç»ä¸º ã€Š{$contextName}ã€‹å®Œæˆç¨¿ä»¶ã€ˆ{$submissionTitle}ã€‰çš„å®¡æŸ¥å·¥ä½œï¼Œå¹¶æå‡ºäº†æˆ‘çš„å»ºè®®ï¼šã€Œ{$recommendation}ã€<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_COMPLETE' AND `locale` = 'zh_CN';
UPDATE `email_templates_default_data` SET `body` = 'Editors:<br />, <br />, I am able and willing to review the submission, "{$submissionTitle}," for {$contextName}. Thank you for thinking of me, and I plan to have the review completed by its due date, {$reviewDueDate}, if not before.<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_CONFIRM' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = 'Editores:<br /><br />Estoy disponible y dispuesto a revisar el envío "{$submissionTitle}" para {$contextName}. Gracias por haber pensado en mí, espero haber completado la revisión para la fecha de entrega, {$reviewDueDate}, si no antes. <br /><br />{$reviewerName}' WHERE `email_key` = 'REVIEW_CONFIRM' AND `locale` = 'es_ES';
