UPDATE `email_templates_default_data` SET `body` = 'Editor:<br />, <br />, Saya dapat dan bersedia melakukan review terhadap naskah, &quot;{$submissionTitle},&quot; untuk {$contextName}. Terimakasih telah mempercayakan kepada saya, dan saya berencana untuk menyelesaikan review ini sesuai tenggat, {$reviewDueDate}, atau sebelumnya.<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_CONFIRM' AND `locale` = 'id_ID';
UPDATE `email_templates_default_data` SET `body` = '{$editorialContactName}:<br />, <br />, æˆ‘å¯ä»¥å¹¶ä¸”æ„¿æ„ä¸ºã€Š{$contextName}ã€‹å®¡æŸ¥ç¨¿ä»¶ã€ˆ{$submissionTitle}ã€‰ã€‚è°¢è°¢æ‚¨è€ƒè™‘æˆ‘å½“å®¡æŸ¥äººï¼Œè€Œæˆ‘è®¡åˆ’åœ¨å®¡æŸ¥æˆªæ­¢æ—¥{$reviewDueDate}å‰å®Œæˆå®¡æŸ¥ã€‚<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_CONFIRM' AND `locale` = 'zh_CN';
UPDATE `email_templates_default_data` SET `body` = 'Editors:<br />, <br />, I am afraid that at this time I am unable to review the submission, "{$submissionTitle}," for {$contextName}. Thank you for thinking of me, and another time feel free to call on me.<br />, <br />, {$reviewerName}' WHERE `email_key` = 'REVIEW_DECLINE' AND `locale` = 'en_US';
