UPDATE `email_templates_default_data` SET `body` = '{$subscriberName}:<br />, <br />, You have now been registered as a subscriber in our online journal management system for {$contextName}, with the following subscription:<br />, <br />, {$subscriptionType}<br />, <br />, To access content that is available only to subscribers, simply log in to the system with your username, "{$username}".<br />, <br />, Once you have logged in to the system you can change your profile details and password at any point.<br />, <br />, Please note that if you have an institutional subscription, there is no need for users at your institution to log in, since requests for subscription content will be automatically authenticated by the system.<br />, <br />, If you have any questions, please feel free to contact me.<br />, <br />, {$subscriptionContactSignature}' WHERE `email_key` = 'SUBSCRIPTION_NOTIFY' AND `locale` = 'en_US';
