UPDATE `email_templates_default_data` SET `body` = 'This email was automatically generated by the {$contextName} thesis abstract submission form.<br />, <br />, Please confirm that the submitted information is correct. Upon receiving your confirmation, the abstract will be published in the online edition of the journal.<br />, <br />, Simply reply to {$thesisName} ({$thesisEmail}) with the contents of this message and your confirmation, as well as any recommended clarifications or corrections.<br />, <br />, Thank you.<br />, <br />, <br />, Title : {$title} <br />, Author : {$studentName}<br />, Degree : {$degree}<br />, Degree Name: {$degreeName}<br />, Department : {$department}<br />, University : {$university}<br />, Acceptance Date : {$dateApproved}<br />, Supervisor : {$supervisorName}<br />, <br />, Abstract<br />, --------<br />, {$abstract}<br />, <br />, {$thesisContactSignature}' WHERE `email_key` = 'THESIS_ABSTRACT_CONFIRM' AND `locale` = 'en_US';
UPDATE `email_templates_default_data` SET `body` = 'El {$contextName} formulario de envío de resumen de tesis generó de forma automática este correo electrónico.<br /><br />Confirme que la información enviada es correcta. Tras recibir la confirmación, el resumen se publicará en la edición en línea de la revista.<br /><br />Responda simplemente a {$thesisName} ({$thesisEmail}) con el contenido de este correo y la confirmación, así como cualquier clarificación o corrección que crea necesaria.<br /><br />Gracias.<br /><br /><br />Título : {$title}<br />Autor/a : {$studentName}<br />Titulación : {$degree}<br />Nombre de la titulación: {$degreeName}<br />Departamento : {$department}<br />Universidad : {$university}<br />Fecha de aceptación: {$dateApproved}<br />Supervisor/a : {$supervisorName}<br /><br />Resumen<br />-------<br />{$abstract}<br /><br />{$thesisContactSignature}' WHERE `email_key` = 'THESIS_ABSTRACT_CONFIRM' AND `locale` = 'es_ES';
UPDATE `email_templates_default_data` SET `body` = 'Mezu hau automatikoki sortu du {$contextName} aldizkariko tesi-laburpena bidaltzeko inprimakiak.<br />, <br />, Mesedez, berretsi bidali diguten informazioa zuzena dela. Zure berrespena jasotzen dugunean, laburpena aldizkariaren lineako edizioan argitaratuko da.<br />, <br />, Besterik gabe, erantzun {$thesisName} mezuari ({$thesisEmail}) mezu honen edukiarekin eta zure berrespenarekin, nahi izanez gero, argibideak eta zuzenketak erantsiz.<br />, <br />, Eskerrik asko.<br />, <br />, <br />, Titulua: {$title} <br />, Egilea: {$studentName}<br />, Gradua: {$degree}<br />, Graduaren izena: {$degreeName}<br />, Saila: {$department}<br />, Unibertsitatea: {$university}<br />, Onartze-data: {$dateApproved}<br />, Zuzendaria: {$supervisorName}<br />, <br />, Laburpena<br />, ------------<br />, {$abstract}<br />, <br />, {$thesisContactSignature}' WHERE `email_key` = 'THESIS_ABSTRACT_CONFIRM' AND `locale` = 'eu_ES';
